/* ===== RSVP JSON (tampil untuk semua orang) ===== */
.rsvp-box {
  display: grid;
  gap: 10px;
  max-width: 640px;
  margin: 0 auto;
  background: #fff;
  border: 1px solid #d5deea;
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.05);
}
.rsvp-stat {
  display: flex;
  gap: 10px;
  margin-bottom: 0;
}
.rsvp-card {
  flex: 1;
  text-align: center;
  border-radius: 10px;
  padding: 10px;
  background: #f6f9fd;
  border: 1px solid #e3ebf5;
}
.rsvp-card b {
  display: block;
  font-size: 22px;
}
.rsvp-card span {
  font-size: 12px;
  color: #5b6b7f;
}
.rsvp-card.hadir b {
  color: #1e9e4a;
}
.rsvp-card.tidak b {
  color: #d04a4a;
}
.rsvp-box input,
.rsvp-box textarea,
.rsvp-box select {
  width: 100%;
  border: 1px solid #d5deea;
  border-radius: 8px;
  padding: 10px 12px;
  margin: 0 0 10px;
  font-size: 14px;
  box-sizing: border-box;
}
.rsvp-box textarea {
  min-height: 80px;
  resize: vertical;
}
.rsvp-box button {
  width: 100%;
  border: 0;
  border-radius: 8px;
  padding: 12px;
  font-size: 15px;
  font-weight: 700;
  background: #b98a2f;
  color: #fff;
  cursor: pointer;
}
.rsvp-box button:disabled {
  opacity: 0.6;
  cursor: wait;
}
.rsvp-msg {
  font-size: 13px;
  margin: 8px 0;
  min-height: 18px;
}
.rsvp-msg.success {
  color: #1e9e4a;
}
.rsvp-msg.error {
  color: #d04a4a;
}
.rsvp-list {
  box-sizing: border-box;
  margin-top: 0;
  height: 278px;
  max-height: 278px;
  overflow-x: hidden;
  overflow-y: scroll;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  scrollbar-color: #54595f #e5e3e3;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.rsvp-list::-webkit-scrollbar {
  width: 10px;
}
.rsvp-list::-webkit-scrollbar-track {
  background: #e5e3e3;
  border-radius: 8px;
}
.rsvp-list::-webkit-scrollbar-thumb {
  background: #54595f;
  border: 2px solid #e5e3e3;
  border-radius: 8px;
}
.rsvp-item {
  box-sizing: border-box;
  display: flex;
  flex: 0 0 86px;
  min-height: 86px;
  gap: 10px;
  background: #f8fafc;
  border: 1px solid #e8eef5;
  border-radius: 10px;
  padding: 10px;
  overflow: hidden;
}
.rsvp-avatar {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  border-radius: 50%;
  background: #b98a2f;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 13px;
}
.rsvp-body {
  flex: 1;
  min-width: 0;
}
.rsvp-head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.rsvp-head strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
}
.rsvp-badge {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 20px;
  color: #fff;
}
.rsvp-badge.hadir {
  background: #1e9e4a;
}
.rsvp-badge.tidak {
  background: #c05656;
}
.rsvp-tgl {
  font-size: 11px;
  color: #8a97a8;
  margin: 2px 0 4px;
}
.rsvp-ucapan {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  font-size: 13.5px;
  line-height: 1.5;
  color: #333;
  word-wrap: break-word;
}
.rsvp-empty {
  text-align: center;
  color: #8a97a8;
  font-size: 13px;
  padding: 20px 10px;
}

/* ===== Animasi RSVP Form — SAMA dengan animasi form Wedding Wish (Elementor: zoomIn + animated-slow + delay 100ms) ===== */
.rsvp-box.elementor-invisible {
  visibility: hidden;
}
.rsvp-box.rsvp-el-animated {
  animation-delay: 0.1s;
}
.rsvp-item {
  animation: rsvpFadeUp 0.5s ease backwards;
}
.rsvp-item:nth-child(1) {
  animation-delay: 0.05s;
}
.rsvp-item:nth-child(2) {
  animation-delay: 0.1s;
}
.rsvp-item:nth-child(3) {
  animation-delay: 0.15s;
}
.rsvp-item:nth-child(n + 4) {
  animation-delay: 0.2s;
}
@keyframes rsvpFadeUp {
  from {
    opacity: 0;
    transform: translate3d(0, 40px, 0);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .rsvp-box {
    transition: none !important;
    transform: none !important;
  }
  .rsvp-box * {
    animation: none !important;
    transition: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
  .rsvp-box.elementor-invisible {
    visibility: visible !important;
  }
}

